type TextBlock =
	| {
			type: 'tag'
			tag: string
			content: string
			language: string | undefined
			args: Record<string, string> | undefined
			original: string
	  }
	| {
			type: 'code'
			content: string
			language: string | undefined
			isPartial: boolean
			original: string
	  }
	| {
			type: 'text'
			content: string
			original: string
	  }

const DEFAULT_TAGS = ['example']

const MAIN_COMPONENT_NAME = 'MainComponent'
const STORY_COMPONENT_NAME = 'StoryComponent'

function buildRegexForTags(t: string[]) {
	// Escape tags for safe regex usage and join them with "|"
	const tagsPattern = t
		.map((tag) => tag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
		.join('|')

	const argsForXMLTagRegex = '((\\s+[\\w-]+=(?:"[^"]*"|\'[^\']*\'))*)'
	// Create a regex pattern to handle both backticks and custom tags
	const regex = new RegExp(
		`(?:\`\`\`(([\\w:]+)\\n)?([\\s\\S]*?)(\\n\`\`\`|$))|(?:<(${tagsPattern})${argsForXMLTagRegex}\\s*>([\\s\\S]*?)<\\/\\5>)`,
		'gi'
	)

	return regex
}

export function splitIntoBlocks(
	input: string,
	additionalTags?: string[]
): TextBlock[] {
	const allTags = [...DEFAULT_TAGS, ...(additionalTags ?? [])]
	const regex = buildRegexForTags(allTags)
	const blocks: TextBlock[] = []
	let lastIndex = 0

	let match: RegExpExecArray | null

	// biome-ignore lint/suspicious/noAssignInExpressions: This is intentional
	while ((match = regex.exec(input)) !== null) {
		// Add the text block before the code block
		if (lastIndex < match.index) {
			const content = input.slice(lastIndex, match.index).trim()
			if (content.length) {
				blocks.push({
					type: 'text',
					content,
					original: content
				})
			}
		}

		// Add the code block
		let type: TextBlock['type'] = 'code'
		let codeBlock = match[0]
		let language = match[2] || undefined
		const isPartial = match[4]?.trim().length === 0

		const tag = match[5]
		const isTagged = tag && allTags.includes(tag)
		if (isTagged) {
			type = 'tag'
			codeBlock = codeBlock
				.replace(new RegExp(`<${tag}[^>]*>`, 'g'), '')
				.replace(new RegExp(`</${tag}>`, 'g'), '')
			language =
				language ?? /```((\w+)\n)?([\s\S]+?)(\n```|$)/g.exec(codeBlock)?.[2]
		}
		const codeContent = codeBlock
			.replace(/```(\s*[\w:]+)?\s*\n|```/g, '')
			.trim()

		if (type === 'code') {
			blocks.push({
				type,
				content: codeContent,
				language,
				isPartial,
				original: match[0]
			})
		}
		if (type === 'tag' && tag) {
			const args = match[6]
				?.trim()
				// match any key-value pair, e.g. `key="value"` or `key='value'`
				.match(/[\w-]+=(?:"[^"]*"|'[^']*')/gm)
				?.reduce((acc, arg) => {
					const [key, ...value] = arg.split('=')
					if (key === undefined || value.length === 0) {
						return acc
					}
					return {
						...acc,
						[key]: value.join('=').replace(/['"]/g, '')
					}
				}, {} as Record<string, string>)
			blocks.push({
				type,
				tag,
				content: codeContent,
				language,
				original: match[0],
				args
			})
		}

		lastIndex = match.index + match[0].length
	}
	if (
		blocks.length === 0 &&
		(input.trim().startsWith(`function ${MAIN_COMPONENT_NAME}(`) ||
			input.trim().startsWith(`export function ${STORY_COMPONENT_NAME}(`))
	) {
		return [
			{
				type: 'code',
				content: input,
				language: 'javascript',
				isPartial: false,
				original: input
			}
		]
	}

	// Add any remaining text after the last code block
	if (lastIndex < input.length) {
		const content = input.slice(lastIndex).trim()
		if (content.length) {
			blocks.push({
				type: 'text',
				content,
				original: content
			})
		}
	}

	return blocks
}
